"""READ-ONLY. ШЛЯХ БЕЗ ПРОПУ: ріст власного рахунку зі складним відсотком (25.11.2026). Питання власниці: як самостійно вийти на $1 000/міс із $4 000.
Потік: СВІНГ спокійні монети (swmfe_trades.csv, atr_pct<2.3%, результат у день виходу, у ризиках R). Ризик на угоду = f% від ПОТОЧНОГО рахунку (щодня перераховується) — це ГІПОТЕЗА про спосіб ведення, не правило стратегії.
1) Історія як була (2022-01…2026-10), старт $4 000. 2) 3 000 перемішаних історій (блоки по 30 днів, seed 7) на 12/24/36 місяців: середина, поганий випадок (гірші 10%), шанс втратити половину рахунку на шляху, шанс дійти до доходу $1 000/міс.
«Дохід на місяць» = рахунок × f × середній місячний результат стратегії в R. Плаваючий мінус відкритих угод тут НЕ врахований (у реальності падіння глибші) — див. примітку у виводі.
Використання: grow.py SW_TRADES [DEPOSIT_PER_MONTH]"""
import os, sys, numpy as np, pandas as pd
HC = float(os.environ.get("HAIRCUT", "0"))        # стрес: яку частку історичної переваги ВІДНЯТИ з кожної угоди (0.5 = «насправді вдвічі слабше»)
sw = pd.read_csv(sys.argv[1]); DEP = float(sys.argv[2]) if len(sys.argv) > 2 else 0.0
g = sw[sw.atr_pct < 0.023]; day = ((g.ts + g.hold * 14400) // 86400).astype(int); R = (g.r - HC * g.r.mean()).groupby(day).sum()
idx = np.arange(day.min(), day.max() + 1); R = R.reindex(idx, fill_value=0.0).to_numpy(); n = len(R); mR = R.sum() / (n / 30.44)
conc = (g.hold * 4 / 24).sum() / n; lev = (1 / g.risk_pct).mean() if g.risk_pct.mean() > 0.2 else (1 / (100 * g.risk_pct)).mean()
print(f"РІСТ РАХУНКУ: СВІНГ спокійні, {len(g)} угод, {n} днів; у середньому {mR:+.1f}R на місяць; одночасно відкрито ≈{conc:.0f} угод; старт $4 000; доплата ${DEP:.0f}/міс; стрес: відняли {100*HC:.0f}% переваги")
def path(r, f, e0=4000.0, dep=0.0):
    e = e0; pk = e0; dd = 0.0; out = np.empty(len(r))
    for i, x in enumerate(r):
        e = max(e * (1 + f * x), 0.0) + dep / 30.44; pk = max(pk, e); dd = min(dd, e / pk - 1); out[i] = e
    return out, dd
FS = tuple(float(x) for x in os.environ.get("FS", "0.0025,0.005,0.01,0.015,0.02,0.03,0.05").split(","))
print("\n== 1) ІСТОРІЯ ЯК БУЛА (4 роки 10 міс.): ризик на угоду, % рахунку → рахунок наприкінці; найглибше падіння; дохід на місяць наприкінці; через скільки місяців дохід став ≥ $1 000/міс")
for f in FS:
    eq, dd = path(R, f, dep=DEP); inc = eq * f * mR; k = np.argmax(inc >= 1000) if (inc >= 1000).any() else -1
    ys = ", ".join(f"{y}: ${eq[min(n-1, int((pd.Timestamp(f'{y}-12-31').timestamp())//86400 - idx[0]))]:,.0f}" for y in (2022, 2023, 2024, 2025))
    print(f"  ризик {100*f:4.2f}% (зараз ${4000*f:5.0f} на угоду): кінець ${eq[-1]:>12,.0f}; падіння {100*dd:4.0f}%; дохід/міс наприкінці ${inc[-1]:>9,.0f}; $1 000/міс — {'через %.0f міс.' % (k/30.44) if k >= 0 else 'не досягнуто'}\n        кінець років: {ys}")
rng = np.random.default_rng(7); B = 30; NS = 3000
print("\n== 2) 3 000 ПЕРЕМІШАНИХ ІСТОРІЙ: середина / поганий випадок (гірші 10%) / добрий (кращі 10%); шанс −50% на шляху; шанс доходу ≥ $1 000/міс наприкінці")
for months in (12, 24, 36):
    L = int(months * 30.44); nb = L // B + 1; print(f"  --- через {months} місяців")
    starts = rng.integers(0, n - B, size=(NS, nb))
    for f in FS:
        fin = np.empty(NS); half = 0; ok = 0
        for s in range(NS):
            r = np.concatenate([R[a:a + B] for a in starts[s]])[:L]; eq, dd = path(r, f, dep=DEP); fin[s] = eq[-1]; half += dd <= -0.5; ok += eq[-1] * f * mR >= 1000
        q = np.percentile(fin, [10, 50, 90])
        print(f"   ризик {100*f:4.2f}%: рахунок ${q[1]:>10,.0f} / ${q[0]:>9,.0f} / ${q[2]:>11,.0f}; дохід/міс у середині ${q[1]*f*mR:>8,.0f}; шанс −50%: {100*half/NS:3.0f}%; шанс $1 000/міс: {100*ok/NS:3.0f}%")
